export const bookGrammar: Record<string, Record<string, GrammarNote[]>> = {"momotaro":{"simplified":[{"example":"山へ行きました。","tip":"Used specifically for moving towards a destination. Often interchangeable with 'に' in basic sentences.","pattern":"Place + へ (e)","jlpt":"N5","meaning":"Particle indicating direction or destination."},{"example":"洗濯に行きました。","tip":"Remove 'ます' from a verb (e.g., 食べます -> 食べ) to use this pattern. In the text, '洗濯' acts as a noun/suru-verb stem.","pattern":"Verb (stem) + に + 行く/来る","jlpt":"N5","meaning":"The purpose of movement (going/coming to do something)."},{"meaning":"Expresses continuation of an action (present progressive).","jlpt":"N4","pattern":"Verb (Te-form) + いる","tip":"When used with 'と' (if/when), it often describes a scene where a sudden discovery is made.","example":"洗濯をしていると、"},{"meaning":"Combining two actions where the first action is done and then the second follows.","jlpt":"N4","tip":"'持って' (hold) + '帰る' (return) means 'to take something back home.'","pattern":"Verb (Te-form) + Verb","example":"持って帰りました。"},{"example":"中から男の子が出て来ました。","tip":"In stories, this is often used when a character or object appears onto the scene.","pattern":"Verb (Te-form) + くる (来ました)","jlpt":"N4","meaning":"An action that comes toward the speaker or the focus of the story."},{"meaning":"When/if one action leads to an immediate result or discovery.","jlpt":"N4","tip":"This 'natural consequence' use is common when opening things or looking somewhere and seeing a result.","pattern":"Verb (Dictionary form) + と","example":"桃を切ると、"},{"example":"きび団子を作ってくれました。","pattern":"Verb (Te-form) + くれる/くれました","tip":"This emphasizes the kindness or benefit received from the person who did the action.","jlpt":"N4","meaning":"To do something as a favor for the speaker or someone the speaker identifies with."}],"intermediate":[{"example":"山へ柴刈りに、お婆さんは川へ洗濯に行きました。","pattern":"Noun + に (行く/来る)","meaning":"Indicates the purpose of movement. Used with verbs like 'to go' or 'to come'.","tip":"The noun must be an action-related noun (like shopping or washing). It answers 'What are you going there to do?'","jlpt":"N5"},{"example":"お婆さんが川で洗濯をしていると","meaning":"Expresses a continuous action or a current state.","pattern":"～ている","tip":"In storytelling, it is often used to set the scene before a main event happens.","jlpt":"N4"},{"jlpt":"N4","example":"きび団子を作ってくれました。","pattern":"～てくれる","meaning":"Used when someone does something for the speaker (or someone close) as a favor.","tip":"This adds a nuance of gratitude. Without it, the sentence would sound like a cold statement of fact."},{"jlpt":"N4","pattern":"～と (Conditional)","meaning":"Indicates that an action lead to an unexpected or natural consequence. 'When [A], then [B]'.","tip":"In fairy tales, this is almost always used to transition to a surprising discovery.","example":"その桃を割ると"},{"jlpt":"N4","tip":"Think of it as movement through space or time towards the current point of the story.","meaning":"Indicates an action coming towards the speaker or a start of a new state.","pattern":"～てくる","example":"流れてきました / 飛び出してきました"},{"jlpt":"N4","example":"鬼退治に行くことを決意しました。","meaning":"Turns a verb/sentence into a noun phrase so it can be treated as an object.","pattern":"Verb (Dictionary form) + こと","tip":"Use this when you want to say you like, decided, or started 'doing' something."}],"original":[{"meaning":"Particle indicating direction or destination.","example":"山へ柴刈りに","jlpt":"N5","tip":"Even though it's written as 'he', it's pronounced 'e' when used as a particle. Focus on the destination!","pattern":"～へ (e)"},{"pattern":"[Noun] + に [Go/Come]","meaning":"Combined with 'to go' (ikimasu/mairimashita), it expresses the objective or purpose of going somewhere.","example":"柴刈りに、洗濯に","jlpt":"N5","tip":"Use this for common activities like shopping (kaimono ni) or lunch (ranchi ni)."},{"jlpt":"N4","tip":"In folk tales, this polite form (kenjougo) is often used by the narrator to show respect or an old-fashioned tone.","example":"住んでおりました","meaning":"The humble/formal version of ～ている, used to describe a continuous state or action.","pattern":"～ております"},{"example":"中より元気な男児が飛び出して参りました","jlpt":"N4","tip":"Here, 'mairu' is the humble version of 'kuru'. It captures the movement of the baby 'coming out' toward the old couple.","meaning":"Indicates that an action is coming toward the speaker or starting to happen.","pattern":"～てくる (参る)"},{"example":"割りましたところ","jlpt":"N3","tip":"Think of this as 'when I did X, I found that Y'. It sets the scene for the discovery of Momotaro.","meaning":"Expresses that one action was immediately followed by a result, often an unexpected one.","pattern":"～たところ"},{"example":"きび団子を拵えてくれました","jlpt":"N4","tip":"This conveys gratitude. It shows the Grandma's kindness in making the dumplings for Momotaro.","meaning":"Indicates that someone did a favor for the speaker or someone they care about.","pattern":"～てくれる"},{"jlpt":"N3","tip":"Use 'koto' when you want to talk about an action as a 'thing' or a 'concept'—like 'the decision TO go'.","example":"鬼征伐に赴くことを決意致しました","meaning":"Turns a verb/clause into a noun phrase, allowing it to function as a direct object.","pattern":"～こと (Nominalization)"}]},"tsuru-no-ongaeshi":{"simplified":[{"pattern":"～ていました","tip":"Focus on the 'state' that continued over a period of time in the past.","meaning":"Continuous state or action in the past (progressive form).","jlpt":"N5","example":"住んでいました"},{"example":"助けてあげました","jlpt":"N5","meaning":"Doing a favor for someone; doing something for the benefit of another.","tip":"Use this when the speaker (or someone they empathize with) performs a kind act for someone else.","pattern":"～てあげる"},{"tip":"Formed by taking the negative (nai) form of the verb and adding 'de kudasai'.","meaning":"Please do not do (negative request).","jlpt":"N5","example":"見ないでください","pattern":"～ないでください"},{"pattern":"V-stem + 始める","jlpt":"N4","example":"織り始めました","meaning":"To start doing something.","tip":"Attach to the stem of the verb (the part before -masu) to indicate the beginning of an action."},{"pattern":"～ている間（は）","example":"織っている間は","jlpt":"N3","tip":"'Aida' describes a continuous period. With 'wa', it often emphasizes the condition or limitation during that time.","meaning":"While; during the time that (continuous state)."},{"tip":"When connecting adjectives, only the final adjective shows the actual tense (past/present).","meaning":"The 'te-form' of an i-adjective used to connect sentences or list qualities.","jlpt":"N5","example":"美しくて","pattern":"い-adjective (remove い) + くて"}],"intermediate":[{"meaning":"Indicates an ongoing action or state in the past (progressive/habitual).","example":"暮らしていました","jlpt":"N5","tip":"Think of this as the past tense of '～ています' (am doing/is doing).","pattern":"～ていました"},{"tip":"Use 'no' instead of 'koto' when you are physically seeing or hearing an action happening.","meaning":"Nominalizes a verb phrase, allowing it to function as a noun (object of the sentence).","example":"鶴が罠に掛かっているのを見つけました","jlpt":"N4","pattern":"～の（を・が）"},{"tip":"Be careful! Using this for people can sound condescending unless it is for family or pets.","example":"解き放ってやりました","meaning":"To do something for someone of lower status, an animal, or a plant.","jlpt":"N4","pattern":"～てやる"},{"jlpt":"N4","meaning":"Appearing to be; looking like (based on visual impression).","example":"嬉しそうに","tip":"Drop the final 'i' of the adjective. Use 'ni' to turn the expression into an adverb.","pattern":"い形容詞（－い）＋ そうに/そう（な）"},{"tip":"Attach 'hajimeru' to the stem of the verb (what remains after removing 'masu').","meaning":"To start doing something.","example":"織り始め","jlpt":"N4","pattern":"Vます（stem）＋ 始める"},{"pattern":"決して ～ ないでください","jlpt":"N3","example":"決して覗かないでください","meaning":"Strongly emphasizes a negative command or prohibition (never...).","tip":"Pairing 'kesshite' with a negative verb adds serious weight to a request or rule."},{"tip":"In this specific context, it means she \"made\" him promise (forced or strongly requested).","example":"約束させました","meaning":"To make or let someone do something.","jlpt":"N3","pattern":"V（使役形）せる・させる"}],"original":[{"meaning":"Present progressive or state of being (humble/polite)","jlpt":"N5","example":"独り暮らしておりました","tip":"This is the humble/polite version of ～ている. In storytelling, it sets a formal, classical tone.","pattern":"～ております"},{"pattern":"V-stem (Conjunctive)","meaning":"The 'masu-stem' used to connect sentences (literary version of ～て)","example":"一羽の鶴が罠に掛かり","tip":"In writing, the stem (掛かり) is used instead of the 'te-form' (掛かって) to sound more formal or elegant.","jlpt":"N4"},{"meaning":"To do something for someone (usually a social inferior or animal)","tip":"Use this when the speaker is performing a favor for animals or people close to them; be careful as it can sound condescending.","example":"解き放ちてやりました","jlpt":"N4","pattern":"～てやる"},{"pattern":"～ほど","meaning":"To the extent that... / So... that...","example":"此の世のものとは思えぬほど","tip":"It expresses a high degree of something by providing an extreme example. Here, the girl is so beautiful she doesn't seem human.","jlpt":"N3"},{"meaning":"Negative suffix (classical version of ～ない)","jlpt":"N2","example":"思えぬほど","tip":"In modern Japanese, you'll see this in fixed expressions or to give a story an 'old-fashioned' feel. 'Omoenu' means 'cannot think/believe'.","pattern":"～ぬ"},{"jlpt":"N1","example":"戸を開くれば","tip":"In classical Japanese (used here for flavor), this 're + ba' structure often means 'when' or 'because' rather than just 'if'.","meaning":"When/If... (classical conditional)","pattern":"～已然形 + ば"}]},"konbini-ningen":{"simplified":[{"pattern":"～ている","meaning":"Actions in progress or a continuous state/habit","tip":"When used with jobs or living situations, it describes a long-term status rather than a momentary action.","jlpt":"N5","example":"働いています"},{"pattern":"～て (Te-form for sequence)","example":"朝六時に起きて、七時に店に着きます。","jlpt":"N5","meaning":"Used to connect sentences or list actions in chronological order","tip":"Think of this as \"and then.\" The tense of the whole sentence is decided by the final verb."},{"meaning":"When X happens, Y naturally or automatically follows","tip":"Use this for constant results, like \"When I push this button, the light turns on,\" or physical changes.","example":"制服を着ると","jlpt":"N4","pattern":"～と (Natural Consequence)"},{"pattern":"～なさい","example":"見つけなさい","jlpt":"N4","tip":"This is stronger than 'te-kudasai' but softer than 'ro' (imperative). It's commonly used in textbooks and instructions.","meaning":"Polite but firm command (often used by parents or teachers)"},{"jlpt":"N3","example":"私にとって","tip":"This is used when giving an evaluation or opinion from a specific person's point of view. It is often followed by adjectives like 'important' or 'difficult.'","meaning":"To me; For me; From my standpoint","pattern":"～にとって"}],"intermediate":[{"pattern":"～続ける (V-stem + 続ける)","tip":"Use the stem form of the verb before 続ける. It implies an uninterrupted or repeated action over time.","meaning":"Continuing to do something; to keep doing.","example":"働き続けています","jlpt":"N4"},{"pattern":"～出す (V-stem + 出す)","example":"動き出します","meaning":"To start or begin doing something (often suddenly or spontaneously).","tip":"Focuses on the outward start of an action, like a machine starting or someone suddenly speaking.","jlpt":"N4"},{"pattern":"～つもり (V-dictionary + つもり)","tip":"Use with the dictionary form for a positive intention and \"nai\" form for an intention NOT to do something.","example":"働くつもりなの","meaning":"Intention to do something; planning to do.","jlpt":"N4"},{"jlpt":"N3","tip":"Used when one action always triggers another. Do not use for everyday routine things like \"every morning.\"","meaning":"Whenever; every time something happens.","example":"聞かれるたびに","pattern":"～たびに (V-dictionary/Noun + の + たびに)"},{"pattern":"～て以来 (V-te + 以来)","meaning":"Ever since; since a certain point in time.","example":"アルバイトを始めて以来","tip":"Used to describe a continuous state that has lasted from a specific past event until now.","jlpt":"N2"},{"pattern":"～がる (Adj-stem + がる)","jlpt":"N3","tip":"Japanese uses this to talk about other people's internal feelings, as you cannot technically 'know' their heart directy.","meaning":"Shows signs of; appears to be (used for the feelings/emotions of others).","example":"不思議がります"}],"original":[{"example":"働き続けるつもりなのか","tip":"Use it only for your own plans or to ask others about theirs; don't use it for superiors.","meaning":"To intention or plan to do something.","pattern":"～つもりだ","jlpt":"N4"},{"jlpt":"N4","pattern":"V-stem + 続ける","meaning":"To continue doing something without stopping.","tip":"Attach this to the masu-stem of any verb to describe an ongoing or repeated action.","example":"勤務し続けている / 働き続ける"},{"example":"離れたことがない","tip":"The negative form of \"koto ga aru\" (have done), used to discuss life experiences.","meaning":"Indicates that one has never had the experience of doing something.","pattern":"V-ta + ことがない","jlpt":"N4"},{"pattern":"V-te + 以来","jlpt":"N3","example":"採用されて以来","tip":"This suggests a continuous state has existed from that specific starting point until now.","meaning":"Ever since a certain point in time; used for something that has continued since then."},{"meaning":"Whenever; every time (something happens, something else happens).","example":"問われる度に","tip":"Use this to emphasize that the second action always follows the first. Do not use it for daily routines.","pattern":"V-dictionary form + 度に","jlpt":"N3"},{"tip":"This is a formal expression used to describe a large scale of time, space, or number.","example":"十八年間に亘り","meaning":"Throughout a period of time or across an entire space.","jlpt":"N2","pattern":"～にわたって / ～にわたり"},{"example":"袖を通す刹那","tip":"A literary and dramatic way to express 'at the moment of.' In daily conversation, 'shunkan' is more common.","meaning":"At the very moment; the instant (something happens).","pattern":"V-dictionary form + 刹那 (せつな)","jlpt":"N1"}]},"ginga-tetsudo":{"simplified":[{"pattern":"～ていました","meaning":"State of being or continuous action (Past progressive)","tip":"Formed by the て-form of a verb + いました. Use it to describe scenes or ongoing actions in the past.","example":"一人で座っていました","jlpt":"N5"},{"pattern":"～が (助詞)","example":"星がたくさん光っていました","tip":"When a new character or object (like the stars or the train) enters the scene, 'ga' is used instead of 'wa'.","jlpt":"N5","meaning":"Indicates the subject of a sentence, especially when introducing new information."},{"jlpt":"N4","example":"白い星の砂が川のように流れていました","tip":"Use 'Noun + のように' to compare something to something else, often used for poetic descriptions.","meaning":"Like; similar to (comparison)","pattern":"～のように"},{"pattern":"～の？","example":"どこへ行くの？","tip":"In casual speech, 'no' replaces 'ka' to turn a sentence into a question with a softer or more curious tone.","jlpt":"N4","meaning":"Casual question marker (sentence ending)"},{"pattern":"Noun + の + Position Noun","meaning":"Location/Position (Above, Outside, etc.)","jlpt":"N4","example":"丘の上に一、窓の外に","tip":"Japanese expresses location by treating the position (top, outside, next to) as a noun connected by 'no'."},{"pattern":"～には / ～では","jlpt":"N3","example":"隣の席には","tip":"Adding 'wa' to 'ni' (at/in) emphasizes that 'in THIS specific place (as opposed to others)', something is happening.","meaning":"Contrastive 'wa' added to particles for emphasis/topic focus."}],"intermediate":[{"example":"寝転んで、... 眺めていました。","tip":"Use this to list actions in chronological order. 'Nekoronde' (lay down) happens before 'nagamete' (gazed).","meaning":"Connecting verbs or states sequentially.","pattern":"～て (Te-form)","jlpt":"N5"},{"example":"眺めていました","tip":"This shows an action was ongoing at a certain point in time in the past.","meaning":"Be doing (continuous action or state in the past).","pattern":"～ていた/～ていました","jlpt":"N5"},{"jlpt":"N4","example":"星屑で出来ているようでした","tip":"Use this when making a comparison based on personal impression or similarity. 'Marude' often accompanies it to mean 'just like'.","meaning":"To look like; to appear to be; to seem.","pattern":"～よう(だ)/～ようです"},{"jlpt":"N4","tip":"In storytelling, this 'to' often marks a moment where a character does something and then notices a new situation.","example":"足を踏み入れると","pattern":"Dict. Form + と","meaning":"When (A) happens, (B) follows (natural consequence or discovery)."},{"example":"どこへ行くんだろう","tip":"This is a combination of the explanatory 'n/no' and the volitional 'darou'. It makes the question sound more reflective or curious.","meaning":"Expressing wonder, doubt, or asking oneself a question.","pattern":"～んだろう / ～のだろう","jlpt":"N3"},{"meaning":"Using a verb directly before a noun to describe it.","pattern":"Verb (Short Form) + Noun","example":"銀色に光る車体","tip":"Unlike English, Japanese doesn't use 'that' or 'which'—just place the action directly in front of the object.","jlpt":"N5"}],"original":[{"tip":"While 'ni' can also show direction, 'e' specifically emphasizes the orientation or heading toward a destination.","pattern":"Place + へ (e)","meaning":"Particle indicating direction of movement","example":"何処へ赴くのであろう","jlpt":"N5"},{"tip":"This is the extra-polite (kenjougo/sonkeigo basis) version of ～ていました. It is very common in formal storytelling.","pattern":"～ておりました (te-orimashita)","meaning":"Continuing state or progressive action (polite)","example":"既に着席しておりました","jlpt":"N4"},{"jlpt":"N4","meaning":"When / If; indicates a natural consequence or a discovery following an action","pattern":"V-dictionary form + と (to)","tip":"In narrative Japanese, it often marks the moment something unexpected happens: 'When I did X, then Y happened.'","example":"車内に足を踏み入れますと"},{"jlpt":"N3","example":"何処へ赴くのであろう","meaning":"I wonder / Shall we; expresses uncertainty or deep pondering to oneself","pattern":"～であろう (de arou) / ～であろうか (de arou ka)","tip":"This is the formal/literary equivalent of 'darou'. It gives the text a philosophical or classical tone."},{"tip":"This is a literary version of '~no you ni'. Use it for formal writing or to sound like a classic novel.","pattern":"～の如く (no gotoku) / ～の如き (no gotoki)","meaning":"Like / As if; used to make a formal simile","example":"大河の如く流転しておりました","jlpt":"N2"},{"jlpt":"N1","example":"一輛の不可思議なる汽車","meaning":"An archaic way to connect an adjective (na-adjective) to a noun","pattern":"～なる (naru) + Noun","tip":"Historically 'naru' replaced the modern 'na'. You will see it in titles or very old-fashioned, high-level literature."}]},"yoru-cafe":{"simplified":[{"jlpt":"N5","meaning":"to become / to get into a state","pattern":"Adjective/Noun + なる","example":"静かになります","tip":"Use 'に' for Na-adjectives and Nouns, but change the 'い' to 'く' for I-adjectives."},{"jlpt":"N5","tip":"In casual speech, the 'い' is often dropped (e.g., 淹れてる).","example":"コーヒーを淹れています","pattern":"V-te + いる","meaning":"progressive action (am/is doing) or state of being"},{"pattern":"V-dictionary form + と","meaning":"natural consequence or \"whenever A happens, B follows\"","tip":"This type of 'if/when' is used for facts, habits, or things that happen automatically.","example":"十時を過ぎると","jlpt":"N4"},{"jlpt":"N4","example":"窓際の席に座っている女性","tip":"In Japanese, the description always comes *before* the noun, unlike English which uses 'who' or 'which' after.","meaning":"using a verb phrase to describe a noun (relative clause)","pattern":"Short form Verb + Noun"},{"meaning":"it seems that... / it looks like... (based on observation)","pattern":"Plain form + ようです","example":"悩みがあるようです","tip":"Use this when you are making a subjective judgment based on what you see or feel.","jlpt":"N3"}],"intermediate":[{"pattern":"～ている","example":"座っています","jlpt":"N5","tip":"For action verbs like 'reading,' it's 'is doing.' For change-of-position verbs like 'sitting,' it's 'is in the state of.'","meaning":"Expresses a continuous state or an ongoing action."},{"jlpt":"N4","tip":"Use this for things that happen automatically, like 'when you push this button' or 'when it gets to 10 PM.'","example":"夜の十時を回ると","meaning":"Expresses a natural consequence or a repeatable cause-and-effect relationship (Whenever A happens, B follows).","pattern":"～と (Conditional)"},{"pattern":"～ために","jlpt":"N4","tip":"When used with a verb, that verb must be in the dictionary (plain) form. It means 'in order to.'","example":"本を読むために","meaning":"Indicates a specific purpose or goal."},{"pattern":"～の（名詞化）","jlpt":"N4","tip":"Use 'no' instead of 'koto' when you are physically seeing or hearing an action happen in real-time.","example":"和らぐのが見えます","meaning":"Turns a verb/clause into a noun so it can be the object of a sentence. Often used with verbs of perception."},{"pattern":"～でしょう","meaning":"Used to express a polite conjecture or a guess about something the speaker isn't 100% sure about.","example":"来ているのでしょう","tip":"It's often paired with 'kitto' (surely/likely) to strengthen the sense of a logical guess.","jlpt":"N4"},{"pattern":"～に身を置く","meaning":"An idiomatic expression meaning to place oneself in a certain environment or situation.","tip":"This is a more literary or formal way to say you are 'staying' or 'spending time' somewhere intentionally.","jlpt":"N3","example":"身を置くために"}],"original":[{"tip":"Words like 'chiisana' and 'ookina' can only be used before a noun, never at the end of a sentence.","meaning":"Used to modify nouns. Note that it is 'chiisana' (adjectival noun style) rather than 'chiisai' (i-adjective).","pattern":"～な (Adjectival Noun)","jlpt":"N5","example":"小さなカフェ"},{"tip":"Use this when speaking about your own actions or things related to you to show respect to the listener.","meaning":"Humble form of ～ている (progressive action or state).","pattern":"～ております","jlpt":"N4","example":"挽いております"},{"pattern":"～て参ります","jlpt":"N4","example":"足を運んで参ります","tip":"In this text, it shows a repeated action coming toward the speaker (the shop) in a polite/business context.","meaning":"Humble form of 'kuru' (to come) or 'iku' (to go)."},{"example":"和らぐのが窺えます","jlpt":"N3","pattern":"Verb (Plain form) + の (Nominalizer)","meaning":"Nominalizes a verb, turning it into a 'thing' or 'act'.","tip":"Use 'no' instead of 'koto' when the following verb involves direct perception (seeing, hearing, feeling)."},{"jlpt":"N3","example":"読書の為ではなく","pattern":"Noun + のため / Verb + ため","tip":"In formal writing or speech, the 'ni' is often omitted from 'tame ni'.","meaning":"Indicates purpose, reason, or benefit (for the sake of / in order to)."},{"meaning":"A formal equivalent of 'deshou', used to express a polite conjecture or deduction.","tip":"This is highly literary or formal. It combines 'de aru' (to be) with the volitional 'shou' to create a high-level guess.","pattern":"～でありましょう","example":"来ているのでありましょう","jlpt":"N2"}]},"yami-no-koe":{"simplified":[{"jlpt":"N5","meaning":"Past tense of an 'na-adjective' or noun.","pattern":"～でした","example":"学校は静かでした","tip":"Use this to talk about how things were in the past. Remember that 'i-adjectives' change to '-katta desu' instead."},{"meaning":"Indicates the purpose of movement (going to do something).","pattern":"V-stem + に (iku/kuru) luxury","example":"忘れ物を取りに","tip":"Remove 'masu' from a verb and add 'ni' + a movement verb to say 'going to [verb]'.","jlpt":"N5"},{"jlpt":"N4","meaning":"Indicates a continuous action or state (progressive).","pattern":"～ている","example":"歩いていると","tip":"Similar to English '-ing'. It describes actions happening right now or persistent states."},{"jlpt":"N4","tip":"In storytelling, this 'to' often signals that the next action happened immediately or was a surprise to the character.","example":"歩いていると / 扉を開けると","pattern":"V-dictionary form + と","meaning":"Natural consequence or unexpected discovery ('when... then...')."},{"meaning":"Audible; something can be heard (spontaneously).","pattern":"～が聞こえる","example":"どこかから声が聞こえました","tip":"Use 'kikoeru' for sounds that reach your ears naturally, and 'kiku' for when you actively listen.","jlpt":"N4"},{"tip":"When an adjective ends in 'te', it often acts like 'and' or 'because' to explain the situation following it.","example":"暗くて何も見えませんでした","pattern":"～て / ～で (te-form)","meaning":"Connecting adjectives or verbs to show cause/reason or sequence.","jlpt":"N4"}],"intermediate":[{"meaning":"The purpose of going or coming somewhere.","pattern":"Verb (stem) + に行く/来る","example":"忘れ物を取りに来た","tip":"Imagine it as 'going/coming for the purpose of [verb]'. Only use the verb stem.","jlpt":"N5"},{"pattern":"Verb (stem) + 始める","meaning":"To start doing something.","tip":"Use this when an action involves some duration or process, rather than an instantaneous change.","example":"歩き始めた","jlpt":"N4"},{"jlpt":"N4","example":"響いているようでした","tip":"Use this for subjective observations based on your senses or feelings. It can also be used for metaphors.","meaning":"To look like, to seem like, or to behave like.","pattern":"～ようだ/～ようです"},{"jlpt":"N3","meaning":"Expectation that something should be the case; it ought to be.","pattern":"～はずだ / ～はずでした","example":"来ただけのはずでした","tip":"Using the past tense 'hazudeshita' often implies that the expectation was wrong or something unexpected happened."},{"jlpt":"N3","example":"水の中を歩いているようでした","tip":"Often translates to 'is currently doing' or 'is in the state of'. Here, it describes a continuous sensation.","meaning":"Continuous state or action (present progressive).","pattern":"～ている (State/Action) ＋ ようだ"},{"jlpt":"N3","pattern":"Verb (dictionary form atau ta-form) + 瞬間 (shunkan)","meaning":"The \"moment\" or \"instant\" something happens. Works like a conjunction.","tip":"This focuses on the precise timing of a change or a new event.","example":"歩き始めた瞬間から"},{"meaning":"An action or sound that starts elsewhere and moves toward the speaker.","pattern":"Verb (te-form) + くる / きます","example":"音楽室の方角から聞こえてきます","tip":"In this context, it describes a sound 'coming' to the listener's ears.","jlpt":"N3"}],"original":[{"pattern":"～ため（に）","meaning":"For the purpose of; in order to. Used to express an objective or reason.","jlpt":"N4","example":"教科書を回収する為だけに","tip":"Used after the dictionary form of a verb or a noun + 'no'. It indicates a clear purpose."},{"pattern":"～はずだ","example":"訪れた筈でありました","jlpt":"N4","tip":"When used in the past tense (~hazudatta), it often implies that what was expected didn't actually happen.","meaning":"Expected to be; should be. Expresses a strong expectation or conviction based on reason."},{"tip":"This is the formal/literary version of 'you da'. 'Gotoki' modifies nouns, 'gotoku' modifies verbs/adjectives.","jlpt":"N2","example":"水中を跋渉しているかの如き","meaning":"As if; like. A literary expression used to make comparisons.","pattern":"～（かの）ごとき / ～（かの）ごとく"},{"pattern":"～せつな（に/より）","meaning":"The moment that...; as soon as. Used to emphasize that two events happen almost simultaneously.","tip":"This is a very formal and dramatic way to say 'the instant' something happens.","example":"踏み出した刹那より","jlpt":"N1"},{"tip":"You will mostly see this in classical literature or very stiff, formal writing. It highlights a contradiction to the previous statement.","jlpt":"N1","example":"然るに","meaning":"And yet; however; nevertheless. A formal conjunctive particle used to show contrast.","pattern":"しかるに"},{"meaning":"The humble/polite version of the continuous state (~te iru).","jlpt":"N3","example":"覆われておりました","tip":"In modern Japanese, this is used in humble speech or very formal narration (Keigo). It replaces 'iru'.","pattern":"～ておる / ～ております"}]}};
